        static bool FloorBlockV4(Product p)
        {
            if (p == null || p.Zone != PressDefs.Zone || !PressDefs.IsMetal(p) || p.State != ProductState.Resting) return false;
            if (p.Body == null || p.Body.isKinematic) return false;
